arguments.command:
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must only use A-Z a-z 0-9 _ . - (Cirrus function URLs reject other keys with 400).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing.
action_from_query() { case "$1" in action=*) echo "${1#action=}" ;; esac; }
EOF
sed -i 's|?/<操作名>`（|?action=<操作名>`（|; s|を取り出し、|を取り出し、|' docs/framework.md
sed -i 's|`?action=<操作名>`（lib/actions.sh の action_url）|`?action=<操作名>`（lib/actions.sh の action_url）。クエリのキーに使える文字は `A-Z a-z 0-9 _ . -` だけ（docs/platform/cirrus-functions.md）。`/` を含むキーは CDN なしの環境で 400 になる|' docs/framework.md
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
# every rendered form URL must have only characters allowed in query keys
for f in event seat refund; do
  bash bin/render $f | grep -o 'action="[^"]*"' | sed 's/action="?//; s/"$//' | while IFS= read -r q; do
    key=${q%%=*}
    [[ "$key" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "invalid query key: $key"; exit 1; }
  done || fail=1
  # round trip: each rendered action is accepted by the handler
  for a in $(cat app/forms/$f.form); do
    bash bin/handle POST "/x?action=$a" | grep -q "^200 $a" || { echo "roundtrip $a"; fail=1; }
  done
done
exit $fail
EOF
bash scripts/verify.sh; echo $?; git diff --stat; cat docs/framework.md

